<script lang="ts">
 import {apiRequest} from '../lib/api';
 import ServiceExecution from './ServiceExecution.svelte';
 let {token,quoteId}:{token:string;quoteId:string}=$props();
 const fields=[['supplier','Identificación legal de Bonaire'],['customer','Identificación legal del cliente o representante'],['site','Lugar de ejecución'],['scope','Alcance y exclusiones'],['payment','Precio y condiciones de pago'],['schedule','Plazos y programación'],['warranty','Garantías y limitaciones'],['obligations','Obligaciones de las partes'],['changes','Cambios, cancelaciones e incumplimientos'],['delivery','Entrega y conformidad']];
 let data=$state<any>(null),busy=$state(false),error=$state(''),notice=$state(''),opened=$state(false),reference=$state(''),terms=$state<Record<string,string>>({}),signedOn=$state(''),evidence=$state(''),reviewed=$state(false),reviewNote=$state(''),legalReviewed=$state(false),editing=$state(false),fileInput:HTMLInputElement;
 const base=()=>'/api/quotes/contracts/'+encodeURIComponent(quoteId);
 const call=(suffix='',body?:unknown)=>apiRequest(base()+suffix,{headers:{Authorization:'Bearer '+token},...(body===undefined?{}:{method:'POST',body:JSON.stringify(body)})});
 async function load(){busy=true;error='';try{data=await call();editing=!data.draft;if(data.draft){reference=data.draft.reference;terms={...data.draft.terms}}else{reference='CTR-'+quoteId.slice(0,24);terms={supplier:'',customer:'',site:data.quote.location||'',scope:data.quote.title,payment:data.quote.payment_terms||'',schedule:data.quote.delivery_terms||'',warranty:data.quote.warranty_terms||'',obligations:'',changes:'',delivery:''}}}catch(e){error=(e as Error).message}finally{busy=false}}
 async function create(e:SubmitEvent){e.preventDefault();if(busy||!window.confirm('¿Guardar este borrador para revisión jurídica y firma? No se marca como firmado.'))return;busy=true;error='';try{await call('',{reference,expected_revision:data.draft?.revision||0,...terms});await load();notice='Borrador conservado. Revísalo antes de firmar.'}catch(e){error=(e as Error).message}finally{busy=false}}
 async function approve(e:SubmitEvent){e.preventDefault();if(busy||!legalReviewed||!window.confirm('¿Confirmas la revisión jurídica y administrativa de esta versión? Se bloqueará para firma.'))return;busy=true;error='';try{await call('/approve',{revision:data.draft.revision,review_note:reviewNote,reviewed:true});await load();notice='Versión aprobada para firma. Todavía no firmada.'}catch(e){error=(e as Error).message}finally{busy=false}}
 const escape=(v:unknown)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
 function documentHtml(){const d=data.draft,q=data.quote;return '<!doctype html><html lang="es"><head><meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src \'unsafe-inline\'"><title>Contrato Bonaire</title><style>@page{size:A4;margin:16mm}body{font:12px/1.5 system-ui;color:#18323a}h1{color:#0f766e}h2{font-size:14px}p{white-space:pre-wrap;overflow-wrap:anywhere}table{width:100%;border-collapse:collapse}td,th{border-bottom:1px solid #ddd;padding:5px;text-align:left}thead{display:table-header-group}tr{break-inside:avoid}footer{margin-top:35px;break-inside:avoid}</style></head><body><h1>BONAIRE · Energía Vital</h1><h2>Contrato de suministro e instalación — '+(data.approved?'versión aprobada para firma':'BORRADOR PARA REVISIÓN')+'</h2><p>Referencia: '+escape(d.reference)+' · Revisión contractual '+escape(d.revision)+' · Presupuesto '+escape(q.id)+' · Revisión '+escape(q.version_no)+'<br>Total de la propuesta aceptada: '+(q.total_cents/100).toFixed(2)+' USD</p>'+fields.map(([k,label],i)=>'<h2>'+(i+1)+'. '+escape(label)+'</h2><p>'+escape(d.terms[k])+'</p>').join('')+'<h2>Anexo económico de la propuesta aceptada</h2><p>'+escape(q.stock_notes||'')+'</p><table><thead><tr><th>Concepto</th><th>Cantidad</th><th>USD/u.</th><th>USD</th></tr></thead><tbody>'+q.items.map((i:any)=>'<tr><td>'+escape(i.description)+'</td><td>'+escape(i.quantity)+'</td><td>'+escape((i.unit_price_usd_cents/100).toFixed(2))+'</td><td>'+escape((i.line_total_usd_cents/100).toFixed(2))+'</td></tr>').join('')+'</tbody></table><p>Subtotal '+(q.subtotal_cents/100).toFixed(2)+' · Impuestos '+(q.taxes_cents/100).toFixed(2)+' · Transporte '+(q.freight_cents/100).toFixed(2)+' · Descuento '+(q.discount_cents/100).toFixed(2)+' USD</p><p><strong>Total: '+(q.total_cents/100).toFixed(2)+' USD</strong></p><footer><p>Lugar y fecha: _______________________________________</p><p>Firma del cliente: ____________________ Firma de Bonaire: ____________________</p><p>'+(data.approved?'Documento preparado para firma de ambas partes.':'BORRADOR: no firmar antes de aprobar la revisión.')+'</p></footer></body></html>'}
 function download(blob:Blob,name:string){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
 function exportDraft(){download(new Blob([documentHtml()],{type:'text/html;charset=utf-8'}),'Bonaire-contrato-'+quoteId+'.html')}
 async function upload(e:SubmitEvent){e.preventDefault();const f=fileInput?.files?.[0];if(busy||!f||!reviewed)return;if(f.size>8*1024*1024||!f.name.toLowerCase().endsWith('.pdf')){error='PDF de hasta 8 MB.';return}if(!window.confirm('¿Confirmas que revisaste las firmas y que el PDF corresponde exactamente a este contrato?'))return;busy=true;error='';try{const bytes=new Uint8Array(await f.arrayBuffer());let raw='';for(let i=0;i<bytes.length;i+=8192)raw+=String.fromCharCode(...bytes.subarray(i,i+8192));await call('/signed',{filename:f.name,pdf:btoa(raw),signed_on:signedOn,evidence,reviewed:true});await load();notice='Copia firmada registrada con huella SHA-256. No se certifica una firma electrónica.'}catch(e){error=(e as Error).message}finally{busy=false}}
 async function downloadSigned(){if(busy)return;busy=true;error='';try{const r=await call('/signed');const bytes=Uint8Array.from(atob(r.pdf),x=>x.charCodeAt(0));download(new Blob([bytes],{type:'application/pdf'}),r.filename)}catch(e){error=(e as Error).message}finally{busy=false}}
</script>
<section class="border rounded-lg p-3 space-y-2">
 <button type="button" class="font-bold text-teal-800 underline" onclick={()=>{opened=!opened;if(opened&&!data)void load()}}>Contrato y firma documental</button>
 {#if opened}
 <p class="text-xs text-slate-600">Modelo preliminar. No sustituye la revisión jurídica, no firma automáticamente y no programa trabajos ni registra pagos.</p>
 {#if error}<p role="alert" class="bg-amber-50 p-2">{error}</p>{/if}{#if notice}<p role="status" class="bg-teal-50 p-2">{notice}</p>{/if}
 {#if data}
 {#if editing&&!data.approved}<form class="space-y-2" onsubmit={create}><label class="block text-sm">Referencia<input class="block w-full border rounded p-2" required minlength="3" maxlength="80" readonly={!!data.draft} bind:value={reference}/></label>{#each fields as [k,label]}<label class="block text-sm">{label}<textarea class="block w-full border rounded p-2" required minlength="3" maxlength={k==='supplier'||k==='customer'?500:1200} bind:value={terms[k]}></textarea></label>{/each}<button type="submit" disabled={busy} class="bg-teal-800 text-white rounded px-3 py-2">Guardar revisión del borrador</button>{#if data.draft}<button type="button" onclick={()=>{editing=false;terms={...data.draft.terms}}} class="ml-2">Cancelar edición</button>{/if}</form>
 {:else}<p class="font-semibold">{data.draft.reference} · R{data.draft.revision}</p><p>Importe aceptado: {(data.quote.total_cents/100).toFixed(2)} USD</p><button type="button" onclick={exportDraft} class="border rounded px-3 py-2">Descargar contrato imprimible</button>
 {#if !data.approved}<button type="button" disabled={busy} onclick={()=>editing=true} class="border rounded px-3 py-2">Nueva revisión</button><form onsubmit={approve} class="border rounded p-3 space-y-2"><label class="block text-sm">Referencia y resultado de la revisión jurídica/administrativa<textarea required minlength="15" maxlength="900" bind:value={reviewNote} class="block w-full border rounded p-2"></textarea></label><label class="flex gap-2 text-sm"><input type="checkbox" required bind:checked={legalReviewed}/> Confirmo que esta versión ha sido revisada y está autorizada para firma.</label><button type="submit" disabled={busy||!legalReviewed} class="rounded bg-teal-800 text-white px-3 py-2">Aprobar para firma</button></form>
 {:else if data.signed}<p class="font-semibold text-teal-800">Evidencia de firma registrada · {data.signed.signed_on}</p><p class="text-xs break-all">SHA-256: {data.signed.sha256}</p><button type="button" disabled={busy} onclick={downloadSigned} class="border rounded px-3 py-2">Descargar copia firmada</button><ServiceExecution {token} {quoteId}/>
 {:else}<form onsubmit={upload} class="border rounded p-3 space-y-2"><p class="font-semibold">Registrar PDF firmado por ambas partes</p><label class="block text-sm">Fecha de firma<input type="date" required bind:value={signedOn} class="block border rounded p-2"/></label><label class="block text-sm">Evidencia y comprobación<textarea required minlength="15" maxlength="900" bind:value={evidence} class="block w-full border rounded p-2"></textarea></label><input type="file" accept=".pdf" required bind:this={fileInput}/><label class="flex gap-2 text-sm"><input type="checkbox" required bind:checked={reviewed}/> Revisé la identidad, ambas firmas y la correspondencia del documento con esta propuesta.</label><button type="submit" disabled={busy||!reviewed} class="bg-teal-800 rounded text-white px-3 py-2">Registrar copia firmada</button></form>{/if}
 {/if}{:else if !busy}<button type="button" onclick={load} class="border rounded px-3 py-2">Reintentar</button>{/if}
 {/if}
</section>
